// Height-accumulating slow event chain: exact CRT and bounded-height literal recurrence.
// Run: node research/lean/negative_min_height_accumulation_audit.mjs
// Full root is generated by CRT, not a guessed residue environment.
function audit(){
 const ok=(b,m)=>{if(!b)throw Error(m)},mod=(a,m)=>(a%m+m)%m;
 const Zmax=150000,comp=new Uint8Array(Zmax+1),primes=[];
 for(let p=2;p<=Zmax;p++)if(!comp[p]){primes.push(p);if(p*p<=Zmax)for(let n=p*p;n<=Zmax;n+=p)comp[n]=1}
 const bigmod=(a,p)=>Number((a%BigInt(p)+BigInt(p))%BigInt(p));
 function inverse(a,p){let t=0,u=1,r=p,s=a;while(s){let q=Math.floor(r/s);[r,s]=[s,r-q*s];[t,u]=[u,t-q*u]}ok(r===1,"inverse");return mod(t,p)}
 function crt(a,m,b,p){let c=mod((b-bigmod(a,p))*inverse(bigmod(m,p),p),p);return [a+m*BigInt(c),m*BigInt(p)]}
 function offsets(ps){let ds=[0];for(let j=ps.length-1;j>=0;j--)ds.unshift(ds[0]+ps[j]-1);return ds}
 function plan(ps){let h=3,ws=[],W=0,G=0;for(let j=0;j<ps.length;j++){let p=ps[j],h1=(j+1)*p,w=h1-h+(p-1)/2;ok(Number.isInteger(w)&&w>0&&w<=2*p,"wait range");ws.push(w);W+=w;G+=p-1;h=h1}return {ws,W,G,h}}
 let tuples=0,pinChecks=0,localChecks=0,examples=[],events=0,ticks=0,eligibleChecks=0,heightChecks=0,tailTicks=0,crtChecks=0;
 function compatible(ps){const ds=offsets(ps),k=ps.length;for(let j=0;j<k;j++)for(let i=0;i<=k;i++)for(let s of [-1,1]){pinChecks++;if((mod(ds[i]-ds[j+1]+s,ps[j])===0)!==(i===j&&s===1))return false}
 for(let q of primes){if(q<=3)continue;if(q>2*k+2)break;let set=new Set(ds.flatMap(d=>[mod(-d-1,q),mod(-d+1,q)]));localChecks++;if(set.size===q)return false}return true}
 for(let k=1;k<=7;k++){
  let found=null;
  function search(ps){if(found)return;if(ps.length===k){tuples++;if(compatible(ps))found=ps;return}
   let j=ps.length+1;
   for(let p of primes){if(p<11||p%12!==7)continue;if(j===1){if(p<127||p>1200)continue}else{let h=(j-1)*ps[j-2];if(p<=ps[j-2]||h/p>j-1.5+.12||h/p<j-1.5+.015)continue}
   search([...ps,p]);if(found)return}
  }
  search([]);ok(found,"find compatible tuple "+k);
  const ps=found,ds=offsets(ps),{ws,W,G,h}=plan(ps),T=3*G,Z=2*T+8;ok(Z<=Zmax&&W<T,"finite bounds");
  let a=BigInt(k%2===0?0:6),m=12n;
  for(let q of primes){if(q<5)continue;if(q>Z)break;let b;
   if(ps.includes(q)){let j=ps.indexOf(q);b=mod(-ds[j+1],q)}
   else {let set=new Set(ds.flatMap(d=>[mod(-d-1,q),mod(-d+1,q)]));b=0;while(set.has(b))b++;ok(b<q,"free prime admissibility")}
   [a,m]=crt(a,m,b,q);ok(bigmod(a,q)===b,"CRT immediate");crtChecks++;
  }
  const x=a+m,A=x+BigInt(ds[0]);ok(A%6n===0n&&A%4n===0n,"canonical");
  for(let j=0;j<k;j++){let target=x+BigInt(ds[j+1]),p=ps[j];ok(bigmod(target,4*p)===mod(2*(j+1)*p,4*p),"signed clock congruence")}
  // Independently calculate the actual candidate divisor sets up to the
  // canonical height cutoff; replay every tick including the final idle tail.
  let pos=A,n=3n-A/2n,t=0,j=0,g=0,wait=0,candidates=null;
  function getCandidates(pos){return primes.filter(p=>p>2&&p<=Z&&(bigmod(pos+1n,p)===0||bigmod(pos-1n,p)===0)).map(p=>({p,plus:bigmod(pos+1n,p)===0}))}
  candidates=getCandidates(pos);
  for(let i=0;i<T;i++){let newn=n+1n,parity=bigmod(newn,2),p=0;wait++;
   for(let cand of candidates){eligibleChecks++;if(cand.plus!==(parity===0))continue;if(bigmod(newn,2*cand.p)===(cand.plus?0:cand.p+2)){p=cand.p;break}}
   if(p){ok(j<k&&p===ps[j]&&wait===ws[j],"literal winner/wait");pos-=BigInt(p-1);g+=p-1;ok(pos===x+BigInt(ds[j+1]),"literal destination");ok(newn+pos/2n===BigInt((j+1)*p),"height accumulation");ok(bigmod(newn,2*p)===0,"even branch");j++;wait=0;events++;candidates=getCandidates(pos)}
   n=newn;t++;ticks++;ok(n+pos/2n===BigInt(3+t-g/2),"height ledger");heightChecks++;
  }
  ok(j===k&&g===G&&pos===x&&wait===T-W,"tail and cumulative gain");tailTicks+=wait;
  examples.push({k,labels:ps,waits:ws,W,G,T,ratio:W/G,completedFraction:W/T,tail:wait,finalHeight:h,digits:A.toString().length,suffix:A.toString().slice(-16)});
 }
 return {tuples,pinChecks,localChecks,crtChecks,events,ticks,eligibleChecks,heightChecks,tailTicks,examples};
}
console.log(JSON.stringify(audit(),null,2));
